pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(to != address(0));
        address[] memory tos = new address[](1);
        tos[0] = to;
        // The buggy version always returns false on non-reverting calls; the reference returns true.
        // The call to caddress may revert for EOAs only if caddress itself reverts, but a plain EOA accepts the call.
        // Use a helper that succeeds to ensure no revert path masks the difference.
        Succeeder s = new Succeeder();
        bool ok = c.transfer(from, address(s), tos, v);
        assertTrue(ok);
    }
}

contract Succeeder {
    fallback() external payable {}
}
